def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp_d = 0
    my_d = 0
    for me, opp in history:
        if opp == 'D':
            opp_d += 1
        if me == 'D':
            my_d += 1
    opp_c = n - opp_d

    recent = history[-12:] if n >= 12 else history
    recent_opp_d = 0
    for _, opp in recent:
        if opp == 'D':
            recent_opp_d += 1

    last_my, last_opp = history[-1]

    if opp_d == 0:
        if n >= 80 and my_d == 0:
            return 'D'
        if my_d > 0 and n >= 82 and last_opp == 'C':
            return 'D'
        return 'C'

    if last_opp == 'D':
        if n >= 2 and history[-1] == ('C', 'D') and history[-2] == ('D', 'C') and recent_opp_d <= 3:
            return 'C'
        if n >= 2 and history[-1] == ('D', 'D') and history[-2] == ('D', 'C') and recent_opp_d <= 5:
            return 'C'
        if (n <= 31 and opp_c > 0 and recent_opp_d <= 6 and
                n >= 2 and history[-1] == ('C', 'D') and history[-2] == ('D', 'D')):
            return 'C'
        if (n <= 30 and opp_c > 0 and recent_opp_d <= 7 and
                n >= 3 and history[-1] == ('D', 'D') and history[-2] == ('D', 'D') and history[-3] == ('D', 'D')):
            return 'C'

    chronic = (n >= 20 and opp_d * 5 >= n * 2) or recent_opp_d >= 8
    if chronic:
        return 'D'

    if last_opp == 'D':
        return 'D'

    return 'C'
